<div class="row">
<div class="col-md-4 mb-3"><label for="employeeCode">Kode pegawai</label><input id="employeeCode" name="employee_code" class="form-control" required maxlength="50" value="{{ old('employee_code',isset($employee) ? $employee->employee_code : '') }}"></div>
